            "R_p": 30,
            "R_n_prim": 30,
            "R_p_prim": 30,
            "R_n_sec": 30,
            "R_p_sec": 30,
        }
        # Reduce the default points for 2D current collectors
        if self.options["dimensionality"] == 2:
            base_var_pts.update({"x_n": 10, "x_s": 10, "x_p": 10})
        return base_var_pts

